"use strict";(globalThis.webpackChunkjc_community_site=globalThis.webpackChunkjc_community_site||[]).push([[66173],{2203(e,t,a){a.r(t),a.d(t,{assets:()=>d,contentTitle:()=>i,default:()=>c,frontMatter:()=>n,metadata:()=>o,toc:()=>l});const o=JSON.parse('{"id":"general/jumpcloud-api-with-hr-amp-asset-management","title":"Jumpcloud Api With Hr Amp Asset Management","description":"By steven","source":"@site/docs/general/jumpcloud-api-with-hr-amp-asset-management.md","sourceDirName":"general","slug":"/general/jumpcloud-api-with-hr-amp-asset-management","permalink":"/jc-community-archive/general/jumpcloud-api-with-hr-amp-asset-management","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Jumpcloud Api With Hr Amp Asset Management","description":"By steven"},"sidebar":"docs","previous":{"title":"Jumpcloud Api With Hr Amp Asset Management","permalink":"/jc-community-archive/general/jumpcloud-api-with-hr-amp-asset-management-922"},"next":{"title":"Jumpcloud Betas","permalink":"/jc-community-archive/general/jumpcloud-betas-593"}}');var r=a(74848),s=a(28453);const n={title:"Jumpcloud Api With Hr Amp Asset Management",description:"By steven"},i=void 0,d={},l=[];function u(e){const t={p:"p",...(0,s.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(t.p,{children:"I'm not sure how to start this, but I wanted to talk about what we're doing internally with HR & Asset Management, how it started, evolved, and where it is now. Hopefully this will spark a conversation about what you're doing and how you got there."}),"\n",(0,r.jsx)(t.p,{children:"Background of our company: We're a website & app development, design, and digital marketing agency in Iowa. I'm our sole IT person and manage 3,000+ websites, 300+ servers, and 60+ computers. Some of our servers are dedicated to 1 client, some of our servers are shared and have at most 50 sites."}),"\n",(0,r.jsx)(t.p,{children:'A few years ago I got tired of developers comping to me multiple times a week asking what server to launch a new site or application to. So that lead to the "Server Dashboard"'}),"\n",(0,r.jsx)(t.p,{children:'First iteration: I built a flat PHP site that pulls data each of our shared servers and shows a very basic "Available, Not Available" dashboard. Each server was hard coded into the page, so obviously not a great long-term solution.'}),"\n",(0,r.jsx)(t.p,{children:'Second iteration: I realized pretty quickly that a flat PHP site with servers hard coded in was not a long term solution. So I rebuilt it into Laravel. Instead of hard coding the servers, I run some API calls against our cloud server provider and pull a list of all of our servers. Then categorize them by "Shared" or "Dedicated" servers. Pretty easy to do because all of our shared servers are named "identifier.company.hosting" - The dedicated servers are the sites URL. Nothing really happens with the dedicated servers, but I do display server info (IP, Datacenter, Hostname, server resources).'}),"\n",(0,r.jsx)(t.p,{children:'Third iteration: I got tired of having a huge spreadsheet tracking all of our computers... so I renamed the "Server Dashboard" to the "Systems Dashboard" and started tracking our Computers and Phones. Each computer and phone are assigned to a user, so I had to create accounts for every employee. Around this time we migrated to JumpCloud, so I integrated into the JC API to create the user itself instead of me adding every employee one-by-one.'}),"\n",(0,r.jsx)(t.p,{children:'Fourth Iteration: A few years before I came to the company, an employee built a web app that would pull every site from our shared servers, and determine if we hosted it or not (Checking site DNS against the server IP). The "Systems Dashboard" that I developed also tracked all of our sites, so I merged the two together. During this time, our lead WordPress developer came to me and asked me to built a "Plugin management" system into the dashboard.'}),"\n",(0,r.jsx)(t.p,{children:'Fifth (and current) Iteration: Decided to go "balls to the wall" and just get rid of all of our previous web apps and spreadsheets. Renamed the "Systems Dashboard" to the "Company-Name Dashboard". This iteration now tracks sites, servers, site logins, Human Resources information, asset and life cycle management.'}),"\n",(0,r.jsx)(t.p,{children:"It's come a long way in 2 years, and has helped us organize our entire company immensely. So what are you all doing to help track your company data? Are you using something custom built or are you using something like ADP or WorkDay? If you're using something like ADP or WorkDay, what are you using to track your infrastructure?"})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(u,{...e})}):u(e)}},28453(e,t,a){a.d(t,{R:()=>n,x:()=>i});var o=a(96540);const r={},s=o.createContext(r);function n(e){const t=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:n(e.components),o.createElement(s.Provider,{value:t},e.children)}}}]);